function biT(key, vars){
  let s = key;
  if(LANG !== 'en'){
    const row = BI_I18N[key];
    if(row){ const idx = LANG === 'zhS' ? 0 : (LANG === 'th' ? 1 : 2); s = row[idx] || key; }
  }
  if(vars) Object.keys(vars).forEach(k=>{ s = s.replace(new RegExp('\\{'+k+'\\}','g'), vars[k]); });
  return s;
}

