// ---------- 畫面切換 ----------
function biShowScreen(id){
  ['biGate','biUpload','biCards'].forEach(s=>{ document.getElementById(s).style.display = (s === id) ? 'flex' : 'none'; });
  document.querySelector('main').style.display = (id === 'biEditor') ? '' : 'none';
}

// ---------- 閘控(規格書§二：前端不持有真值，只轉發使用者輸入；driven by /verify-code) ----------
async function biVerifyCode(code){
  try {
    const fd = new FormData(); fd.append('code', code);
    const resp = await fetch(BI_API_BASE + '/verify-code', { method:'POST', headers:{'x-api-token': BI_API_TOKEN}, body: fd });
    if(!resp.ok) return (resp.status === 401) ? null : false; // 401=api token本身有問題(不該發生)，跟code錯誤分開處理更保守地當網路問題
    const data = await resp.json().catch(()=>null);
    return data ? !!data.valid : null;
  } catch(err){ return null; }  // 網路錯誤跟code錯誤(false)分開：網路錯誤不能拿使用者輸入的code去覆蓋sessionStorage判斷
}

function biGateError(msg){
  // 2026-08-22正式環境e2e測試發現的真bug：`.bi-err`這個class本身CSS就是display:none，
  // 這裡原本寫`style.display=''`只是清掉inline覆蓋、退回class預設值(還是none)，等於錯誤文字
  // 永遠不會真的顯示出來——文字內容(textContent)是對的，畫面上就是看不到，純程式碼審查不會發現，
  // 一定要實際截圖看畫面才抓到(跟C1遮罩案例、BI_EXAMPLES key不對稱案例同一種「數值/DOM正確但
  // 視覺不對」陷阱)。改用明確的'block'覆蓋CSS class的display:none。
  const el = document.getElementById('biGateErr');
  el.textContent = msg; el.style.display = msg ? 'block' : 'none';
}

document.getElementById('biGateForm').addEventListener('submit', async e=>{
  e.preventDefault();
  const code = document.getElementById('biCodeInput').value.trim();
  if(!code) return;
  const btn = document.getElementById('biGateBtn');
  btn.disabled = true; biGateError('');
  const ok = await biVerifyCode(code);
  btn.disabled = false;
  if(ok === true){
    sessionStorage.setItem('biAccessCode', code);
    biShowScreen('biUpload');
  } else if(ok === false){
    biGateError(biT("That code didn't work — please check and try again."));
  } else {
    biGateError(biT('Could not reach the system right now — please try again in a moment.'));
  }
});

(async function biAutoGate(){
  const saved = sessionStorage.getItem('biAccessCode');
  if(!saved){ biShowScreen('biGate'); return; }
  const ok = await biVerifyCode(saved);
  biShowScreen(ok === true ? 'biUpload' : 'biGate');
})();

// ---------- 造型基準與4款變化(規格書§三/§5.3) ----------
const BI_EGG_RANGE = [0, 30], BI_TAPER_RANGE = [60, 100];  // 對應面板滑桿rE/rS的合法範圍(medium.html)
function biClamp(v, range, fallback){
  if(typeof v !== 'number' || isNaN(v)) return fallback;
  return Math.max(range[0], Math.min(range[1], v));
}

function biBuildBase(d){
  const L = (typeof d.外部長度_mm === 'number' && d.外部長度_mm > 0) ? d.外部長度_mm : 1700;
  const W = (typeof d.外部寬度_mm === 'number' && d.外部寬度_mm > 0) ? d.外部寬度_mm : 800;
  const egg = biClamp(d.蛋形係數_pct, BI_EGG_RANGE, 0);
  const taper = biClamp(d.底部收縮_pct, BI_TAPER_RANGE, 74);  // API的taper是為浴缸壁設計，套在臉盆凹陷遮罩上常常超出合法範圍(demo實測115.9/167.1)，這裡clamp
  const customPts = (Array.isArray(d.手繪俯視輪廓_normalized) && d.手繪俯視輪廓_normalized.length >= 8)
    ? d.手繪俯視輪廓_normalized.slice() : null;
  const shape = customPts ? 'custom' : 'ellipse';
  return {
    L, W, H:580, b:130, t:20, lip:20, r:150,
    obL: Math.round(L*0.744/2)*2, obW: Math.round(W*0.75/2)*2,
    ibL: Math.round(L*0.6925/2)*2, ibW: Math.round(W*0.6475/2)*2,
    riL: Math.round(1001*L/1600), riW: Math.round(1152*W/800),
    roL: Math.round(887*L/1600),  roW: Math.round(1743*W/800),
    wallMode:'factory', dH:0, egg, arc:60, taper, rim:'round',
    drain:'center', slope:1.5, ovf:false, ovfDrop:75, undercut:false, skirt:false,
    shape, customPts,
  };
}

function biNormRescale(pts){
  const xs = pts.map(p=>p[0]), ys = pts.map(p=>p[1]);
  const minX = Math.min.apply(null, xs), maxX = Math.max.apply(null, xs);
  const minY = Math.min.apply(null, ys), maxY = Math.max.apply(null, ys);
  const cx = (minX+maxX)/2, cy = (minY+maxY)/2;
  const scale = Math.max(maxX-minX, maxY-minY) || 1;
  return pts.map(p=>[(p[0]-cx)/scale, (p[1]-cy)/scale]);
}

function biSmoothOutline(pts, passes){
  let out = pts;
  for(let pass=0; pass<(passes||1); pass++){
    const n = out.length, prev = out;
    out = prev.map((p,i)=>{
      let sx=0, sy=0;
      for(let k=-2;k<=2;k++){ const q = prev[(i+k+n)%n]; sx+=q[0]; sy+=q[1]; }
      return [sx/5, sy/5];
    });
  }
  return out;
}

// 四個變化軸(規格書§三，係數初步提案，依實測校準——比照wizard.js既有慣例)
function biVariants(apiDesignParams){
  const base = biBuildBase(apiDesignParams);
  const variants = [];
  variants.push({ name: biT('Faithful curve'), params: Object.assign({}, base) });
  variants.push({ name: biT('Deep soak'), params: Object.assign({}, base, { H: base.H + 90 }) });
  const stretchedL = Math.round(base.L * 1.2 / 10) * 10;
  variants.push({ name: biT('Elongated'), params: Object.assign({}, base, {
    L: stretchedL,
    obL: Math.round(stretchedL*0.744/2)*2, riL: Math.round(1001*stretchedL/1600), roL: Math.round(887*stretchedL/1600),
    ibL: Math.round(stretchedL*0.6925/2)*2,
  }) });
  const smoothPts = base.customPts ? biNormRescale(biSmoothOutline(base.customPts, 2)) : null;
  variants.push({ name: biT('Softened'), params: Object.assign({}, base, {
    customPts: smoothPts || base.customPts,
    egg: biClamp((base.egg||0) + 10, BI_EGG_RANGE, base.egg),
    rim: 'round',
  }) });
  return variants;
}

// ---------- 4提案卡生成(複用wizard.js的captureRenders模式，函式名不同避免混淆) ----------
let BI_PROPS = [];
async function biGenerateProposals(designParams, isExample){
  const variants = biVariants(designParams);
  const saved = {}; Object.keys(P).forEach(k=>{ saved[k] = P[k]; });
  BI_PROPS = [];
  for(const v of variants){
    Object.assign(P, v.params);
    P.customPtsInner = null; P.customProfile = null; P.wallMod = null; P.rimMod = null;
    P.drainPos = null; P.ovfPos = null; P.faucetPos = null;
    buildTub();
    const img = (await captureRenders({ w:520, h:390, mime:'image/jpeg', q:0.82, shots:[['thumb', Math.PI/4, Math.PI/3.2]], noWatermark:true }))[0][1];
    BI_PROPS.push({ name: v.name, params: v.params, img, dims: `${v.params.L} × ${v.params.W} mm` });
  }
  Object.keys(saved).forEach(k=>{ P[k] = saved[k]; });
  syncUI(); buildTub();
  biRenderCards(isExample);
}

function biRenderCards(isExample){
  const g = document.getElementById('biPropGrid');
  g.innerHTML = '';
  BI_PROPS.forEach((p,i)=>{
    const card = document.createElement('div');
    card.className = 'prop-card';
    card.innerHTML = `<img src="${p.img}" alt="${p.name}"><div class="pc-body"><b>${p.name}</b><span>${p.dims}</span></div>`;
    card.addEventListener('click', ()=> biApplyProposal(i));
    g.appendChild(card);
  });
  document.getElementById('biExampleFlag').style.display = isExample ? '' : 'none';
  biShowScreen('biCards');
}

function biApplyProposal(i){
  const p = BI_PROPS[i].params;
  Object.assign(P, p);
  P.customPtsInner = null; P.customProfile = null; P.wallMod = null; P.rimMod = null;
  P.drainPos = null; P.ovfPos = null; P.faucetPos = null;
  syncUI(); buildTub();
  biShowScreen('biEditor');
}

document.getElementById('biBackBtn').addEventListener('click', ()=> biShowScreen('biUpload'));

// ---------- 上傳流程 ----------
function biShowStatus(kind, msg){
  // 同biGateError()的修正理由：明確用'block'而不是''，不要依賴目標元素當前的class剛好沒設
  // display:none這種脆弱假設(這裡是#biUploadStatus/.tip，目前.tip沒設display，但不該靠這個巧合)。
  const el = document.getElementById('biUploadStatus');
  el.style.color = (kind === 'err') ? '#a04b2e' : '';
  el.textContent = msg || '';
  el.style.display = msg ? 'block' : 'none';
}

async function biHandleUpload(file){
  if(!file) return;
  const btn = document.getElementById('biUploadBtn');
  btn.style.pointerEvents = 'none'; btn.style.opacity = '.6';
  biShowStatus('progress', biT('Uploading & analysing… usually 30–90 seconds, longer if the system just woke up.'));

  const fd = new FormData();
  fd.append('files', file, file.name || 'basin.jpg');
  fd.append('mode', 'basin_inspire');
  fd.append('access_code', sessionStorage.getItem('biAccessCode') || '');

  let resp, data;
  try {
    resp = await fetch(BI_API_BASE + '/reconstruct', { method:'POST', headers:{'x-api-token': BI_API_TOKEN}, body: fd });
    data = await resp.json().catch(()=>null);
  } catch(err){
    // 規格書§十一(08裁定「直接做，不等網路確認」)：真正的網路/連線失敗(fetch本身拋錯，不是
    // 伺服器回了錯誤狀態碼)才自動切範例——401/422/429等是「網路通、伺服器有回應」的正常錯誤路徑，
    // 那些狀況硬塞一個範例反而誤導使用者(以為自己的照片有效，其實是code錯或真的沒認出臉盆)。
    btn.style.pointerEvents = ''; btn.style.opacity = '';
    biShowStatus('err', biT('Network issue — showing a pre-made example instead.'));
    await biGenerateProposals(biExampleToDesignParams(BI_EXAMPLES.countertop), true);
    return;
  }
  btn.style.pointerEvents = ''; btn.style.opacity = '';

  if(!resp.ok){
    if(resp.status === 401){
      sessionStorage.removeItem('biAccessCode');
      biShowStatus('', '');
      biGateError(biT('Your access code is no longer valid — please enter it again.'));
      biShowScreen('biGate');
      return;
    }
    biShowStatus('err', biT("We couldn't clearly recognise a basin in this photo — try a clearer, closer shot of just the basin."));
    return;
  }

  biShowStatus('', '');
  await biGenerateProposals(data.spec['設計參數'] || {}, false);
}

document.getElementById('biUploadFile').addEventListener('change', e=>{
  biHandleUpload(e.target.files[0]);
  e.target.value = '';
});

// ---------- 範例模式(規格書§十一，08裁定重新定位成常設教具+後備，非只在網路差時出現) ----------
// BI_EXAMPLES用扁平英文key(L/W/egg/taper/customPts)方便閱讀/維護，這裡轉換成biBuildBase()
// 預期的中文key格式(跟真實API的data.spec['設計參數']同一套鍵名)，兩邊資料結構才對得起來——
// 2026-08-22本機測試時發現的真bug：漏了這層轉換，範例會悄悄退回預設橢圓(L1700/W800/無customPts)，
// 縮圖看起來「像模像樣」但其實完全沒用到範例資料，是視覺假象不是真的成功(跟C1案例同一種教訓)。
function biExampleToDesignParams(ex){
  return {
    外部長度_mm: ex.L, 外部寬度_mm: ex.W,
    蛋形係數_pct: ex.egg, 底部收縮_pct: ex.taper,
    手繪俯視輪廓_normalized: ex.customPts, shape_code: ex.shape_code,
  };
}
document.querySelectorAll('#biExampleBtns button[data-example]').forEach(b=>{
  b.addEventListener('click', ()=> biGenerateProposals(biExampleToDesignParams(BI_EXAMPLES[b.dataset.example]), true));
});
